import fs from 'node:fs';
import os from 'node:os';
const h=os.homedir();
fs.writeFileSync('.dip-local/redaction-fixture.json',JSON.stringify({completedAt:'test',preflight:true,protocol:{instructions:'official requirements'},pairs:[],paths:[h,h.replaceAll('\\','/'),h.replaceAll('\\','\\\\'),h.replaceAll('\\','\\\\\\\\')],url:'https://example.invalid/file?se=123&sig=PRIVATE-SAMPLE&sp=r'}));
'@ | node --input-type=module
node scripts/longitudinal-redact.mjs .dip-local/redaction-fixture.json
@'
import fs from 'node:fs';
import assert from 'node:assert/strict';
const d=JSON.parse(fs.readFileSync('.dip-local/redaction-fixture.json'));
assert.equal(d.protocol.instructions,'official requirements');
assert.ok(d.paths.every(x=>x==='<home>'));
assert.ok(d.url.includes('sig=[REDACTED]'));
assert.ok(!d.url.includes('PRIVATE-SAMPLE'));
console.log('Redaction preserves registered text and covers all path forms.');
